<!DOCTYPE html><html><head><title>Admin</title><link rel='stylesheet' href='assets/css/admin.css'></head><body><div class='wrap'><div class='box'><h1>Kelola Menu</h1><form method='post' enctype='multipart/form-data'><input name='nama' placeholder='Nama Menu' required><input name='harga' placeholder='Harga' required><input type='file' name='gambar'><button name='add'>Tambah Menu</button></form></div><div class='box'><h2>Daftar Menu</h2><?php foreach($menu as $i=>$x): ?><div class='item'><img src='assets/images/<?= $x['gambar'] ?>'><form method='post' enctype='multipart/form-data' class='edit'><input type='hidden' name='id' value='<?= $i ?>'><input name='nama' value='<?= $x['nama'] ?>'><input name='harga' value='<?= $x['harga'] ?>'><input type='file' name='gambar'><button name='update'>Update</button><a class='del' href='index.php?page=admin&delete=<?= $i ?>'>Hapus</a></form></div><?php endforeach; ?></div><div class='box'><h2>Daftar Booking</h2><?php foreach($bookings as $i=>$b): ?><div class='book'><div><strong><?= $b['nama'] ?></strong><p><?= $b['tanggal'] ?> <?= $b['jam'] ?> | <?= $b['orang'] ?> orang</p></div><form method='post'><input type='hidden' name='id' value='<?= $i ?>'><select name='booking_status'><option>Pending</option><option>Confirmed</option><option>Done</option><option>Cancelled</option></select><button name='status'>Update</button><a class='del' href='index.php?page=admin&delbook=<?= $i ?>'>Hapus</a></form></div><?php endforeach; ?></div></div></body></html>